/**
 * A base class for unarchivers that provides common extraction logic.
 *
 * <p>This implementation protects against the Zip‑Slip vulnerability by validating
 * the resolved extraction path before any file system operations are performed.</p>
 */
public abstract class AbstractUnArchiver extends AbstractLogEnabled implements UnArchiver, FinalizerEnabled {

    private boolean overwrite = true;
    private boolean ignorePermissions = false;

    // other methods

    /**
     * Extracts a single entry from an archive.
     *
     * @param srcF              the source archive file (unused but kept for API compatibility)
     * @param dir               the target extraction directory
     * @param compressedInputStream the input stream containing the entry data
     * @param entryName         the name of the entry inside the archive
     * @param entryDate         the modification time of the entry
     * @param isDirectory       whether the entry represents a directory
     * @param mode              the Unix permission mode (may be {@code null})
     * @param symlinkDestination the target of a symbolic link (may be {@code null} or empty)
     * @throws IOException      if an I/O error occurs
     * @throws ArchiverException if the entry would extract outside the target directory
     */
    protected void extractFile(final File srcF,
                               final File dir,
                               final InputStream compressedInputStream,
                               final String entryName,
                               final Date entryDate,
                               final boolean isDirectory,
                               final Integer mode,
                               String symlinkDestination) throws IOException, ArchiverException {

        // Resolve the target file and canonicalise both the target directory and the resolved file.
        final File canonicalDir = dir.getCanonicalFile();
        final File resolvedFile = new File(canonicalDir, entryName).getCanonicalFile();

        // Verify that the resolved file is still inside the target directory.
        if (!resolvedFile.getPath().startsWith(canonicalDir.getPath())) {
            throw new ArchiverException("Entry '" + entryName + "' is outside the target directory");
        }

        final File f = resolvedFile;

        try {
            // Skip extraction if the file already exists and overwrite is disabled.
            if (!isOverwrite() && f.exists() && (f.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Ensure parent directories exist.
            final File dirF = f.getParentFile();
            if (dirF != null && !dirF.exists()) {
                if (!dirF.mkdirs()) {
                    throw new ArchiverException("Failed to create directory: " + dirF);
                }
            }

            if (!StringUtils.isEmpty(symlinkDestination)) {
                // Create a symbolic link. The destination is left untouched because
                // the caller is responsible for ensuring it is safe.
                SymlinkUtils.createSymbolicLink(f, new File(symlinkDestination));
            } else if (isDirectory) {
                if (!f.exists() && !f.mkdirs()) {
                    throw new ArchiverException("Failed to create directory: " + f);
                }
            } else {
                // Write the file contents.
                try (OutputStream out = new FileOutputStream(f)) {
                    IOUtil.copy(compressedInputStream, out);
                }
            }

            // Preserve the original modification time.
            f.setLastModified(entryDate.getTime());

            // Apply Unix permissions if requested.
            if (!isIgnorePermissions() && mode != null && !isDirectory) {
                ArchiveEntryUtils.chmod(f, mode);
            }
        } catch (final FileNotFoundException ex) {
            getLogger().warn("Unable to expand to file " + f.getPath(), ex);
        }
    }

    // other methods

    @Override
    public boolean isIgnorePermissions() {
        return ignorePermissions;
    }

    @Override
    public boolean isOverwrite() {
        return overwrite;
    }

}
