private void validateSignatureCoverage(org.opensaml.saml.saml2.core.SAMLObject samlObject) throws WSSecurityException {
    if (samlObject == null) {
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
    String id = samlObject.getID();
    if (id == null || id.isEmpty()) {
