    }
    Signature sig = samlObject.getSignature();
    if (sig == null) {
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
    List<Reference> refs = sig.getSignedInfo().getReferences();
    if (refs == null || refs.size() != 1) {
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
    Reference ref = refs.get(0);
    String uri = ref.getURI();
    if (!("#" + id).equals(uri)) {
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
    // Check algorithm
    String algo = sig.getSignedInfo().getSignatureMethod().getAlgorithm();
    if (algo == null) {
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
    // Reject weak algorithms
    if (algo.toLowerCase().contains("sha1") || algo.toLowerCase().contains("hmac")) {
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }
}

