     * @return a normalized path starting with a single slash, or {@code null} if {@code path} is {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Empty string should become "/"
        if (path.isEmpty()) {
            return "/";
        }

        int i = 0;
        // Count leading slashes
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // Remaining part after leading slashes
        final String rest = path.substring(i);

        // Ensure a single leading slash
        return "/" + rest;
    }

