     *
     * <p>This method rejects paths containing directory traversal sequences,
     * back‑slashes, double slashes, or percent‑encoded dots. It also normalises
     * the URI and ensures that the resulting path does not contain any
     * {@code ..} segments.</p>
     *
     * @param path the raw resource path
     * @return {@code true} if the path is considered safe, {@code false} otherwise
     */
    private boolean isSafePath(String path) {
        // Reject obvious traversal attempts
        if (path.contains("..") || path.contains("\\") || path.contains("//")) {
            return false;
