    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical (real) path of the target directory once.
        Path targetPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Reject empty names – they could lead to ambiguous behavior.
            if (entryName == null || entryName.trim().isEmpty()) {
                throw new IOException("archive entry has an empty name");
            }

            // Reject absolute paths (both Unix and Windows styles).
            if (Paths.get(entryName).isAbsolute()) {
                throw new IOException("archive entry uses an absolute path: " + entryName);
            }

            // Reject names that explicitly attempt to traverse upwards.
            if (entryName.contains("..")) {
                throw new IOException("archive entry contains forbidden '..' component: " + entryName);
            }

            // Resolve the entry against the target directory and normalize.
            Path entryPath = targetPath.resolve(entryName).normalize();

            // Ensure the resolved path is still within the target directory.
            if (!entryPath.startsWith(targetPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            File f = entryPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                File parent = f.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }
                try (OutputStream o = Files.newOutputStream(entryPath)) {
                    writer.writeEntryDataTo(nextEntry, o);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

