    // other methods

    /**
     * Converts a {@link StreamSource} into a {@link SAXSource} while protecting
     * against XML External Entity (XXE) attacks. The method explicitly disables
     * all forms of external entity resolution and DTD processing.
     *
     * @param source   the source XML stream
     * @param exchange optional Camel exchange that may contain a pre‑configured
     *                 {@link SAXParserFactory}
     * @return a secure {@link SAXSource}
     * @throws SAXException if the parser cannot be created
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        // Build an InputSource from the StreamSource
        InputSource inputSource = (source.getReader() != null)
                ? new InputSource(source.getReader())
                : new InputSource(source.getInputStream());

        if (source.getSystemId() != null) {
            inputSource.setSystemId(source.getSystemId());
        }
        if (source.getPublicId() != null) {
            inputSource.setPublicId(source.getPublicId());
        }

        XMLReader xmlReader = null;
        SAXParserFactory factory = null;

        try {
            // Reuse a factory from the exchange if available
            if (exchange != null) {
                factory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }

            if (factory == null) {
                factory = SAXParserFactory.newInstance();
            }

            // Enable secure processing
            try {
                factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            } catch (Exception e) {
                LOG.warn("Failed to enable FEATURE_SECURE_PROCESSING: {}", e.toString());
            }

            // Disable all external entity resolution
            try {
                factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            } catch (Exception e) {
                LOG.debug("Feature external-general-entities not supported: {}", e.toString());
            }
            try {
                factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            } catch (Exception e) {
                LOG.debug("Feature external-parameter-entities not supported: {}", e.toString());
            }

            // Disallow DOCTYPE declarations entirely
            try {
                factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (Exception e) {
                LOG.debug("Feature disallow-doctype-decl not supported: {}", e.toString());
            }

            // Prevent loading external DTDs
            try {
                factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            } catch (Exception e) {
                LOG.debug("Feature load-external-dtd not supported: {}", e.toString());
            }

            // Optional: avoid loading DTD grammar
            try {
                factory.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            } catch (Exception e) {
                LOG.debug("Feature load-dtd-grammar not supported: {}", e.toString());
            }

            factory.setNamespaceAware(true);

            SAXParser parser = factory.newSAXParser();
            xmlReader = parser.getXMLReader();

        } catch (Exception ex) {
            LOG.warn("Unable to create a secure SAXParser/XMLReader: {}", ex.toString());
        }

        // Fallback: if we still don't have a reader, attempt a minimal secure parser
        if (xmlReader == null) {
            try {
                SAXParserFactory fallbackFactory = SAXParserFactory.newInstance();
                fallbackFactory.setNamespaceAware(true);
